def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion at beginning
    if s_in[:min_len] == s_out[:min_len]:
        if len(s_in) > len(s_out):
            return (s_in[min_len:], "", min_len)  # deletion
        else:
            return ("", s_out[min_len:], min_len)  # insertion

    # Check for insertion/deletion at end  
    if s_in[-min_len:] == s_out[-min_len:]:
        if len(s_in) > len(s_out):
            return (s_in[:-min_len], "", 0)  # deletion
        else:
            return ("", s_out[:-min_len], 0)  # insertion

    # Look for substitution or replacement
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're replacing a substring
            # Try to find longest matching prefix/suffix
            # For now, let's just return the first difference
            old_char = s_in[i]
            new_char = s_out[i]
            return (old_char, new_char, i)

    # If we reach here, one string is a prefix of the other
    if len(s_in) > len(s_out):
        return (s_in[min_len:], "", min_len)
    elif len(s_out) > len(s_in):
        return ("", s_out[min_len:], min_len)
    else:
        return ("", "", -1)  # No difference

# Analyze each changed pair
changed_pairs = [(0, 'wfuee', 'wewee'), (2, 'ifuyby', 'iewaba'), (4, 'ykkw', 'ufikw')]

for idx, inp, out in changed_pairs:
    old_sub, new_sub, pos = find_minimal_edit(inp, out)
    print(f"Pair {idx}: '{inp}' -> '{out}'")
    print(f"  Change: '{old_sub}' -> '{new_sub}' at position {pos}")
    print()

